 61	static void *display_audio_worker(void *arg)
 62	{
 63	  velawear_display_t *display = (velawear_display_t *)arg;
 64	  uint8_t job;
 65	  int ret;
 66	
 67	  pthread_mutex_lock(&display->lock);
 68	  job = display->audio_job;
 69	  pthread_mutex_unlock(&display->lock);
 70	
 71	  if (job == DISPLAY_AUDIO_JOB_MIC)
 72	    {
 73	      ret = velawear_mic_hw_test();
 74	    }
 75	  else
 76	    {
 77	      ret = velawear_music_hw_test();
 78	    }
 79	
 80	  pthread_mutex_lock(&display->lock);
 81	  display->audio_test_result = ret;
 82	  display->audio_test_running = false;
 83	  pthread_mutex_unlock(&display->lock);
 84	  return NULL;
 85	}
