 87	static int display_audio_start(velawear_display_t *display, uint8_t job)
 88	{
 89	  pthread_t finished_thread;
 90	  bool reap_finished = false;
 91	  int ret;
 92	
 93	  pthread_mutex_lock(&display->lock);
 94	  if (display->audio_test_running)
 95	    {
 96	      pthread_mutex_unlock(&display->lock);
 97	      return 1;
 98	    }
 99	
100	  if (display->audio_thread_started)
101	    {
102	      finished_thread = display->audio_thread;
103	      display->audio_thread_started = false;
104	      reap_finished = true;
105	    }
106	
107	  display->audio_job = job;
108	  display->audio_test_result = -1;
109	  display->audio_test_running = true;
110	  pthread_mutex_unlock(&display->lock);
111	
112	  if (reap_finished)
113	    {
114	      pthread_join(finished_thread, NULL);
115	    }
116	
117	  ret = pthread_create(&display->audio_thread, NULL,
118	                       display_audio_worker, display);
119	  if (ret != 0)
120	    {
121	      pthread_mutex_lock(&display->lock);
122	      display->audio_test_running = false;
123	      pthread_mutex_unlock(&display->lock);
124	      syslog(LOG_ERR, "[Display] audio worker create failed: %d\n", ret);
125	      return -1;
126	    }
127	
128	  pthread_mutex_lock(&display->lock);
129	  display->audio_thread_started = true;
130	  pthread_mutex_unlock(&display->lock);
131	  return 0;
132	}
