258	static void display_queue_companion_prompt(velawear_display_t *display,
259	                                           const char *prompt)
260	{
261	  velawear_event_t event;
262	  size_t length;
263	  int ret;
264	
265	  if (display == NULL || display->events == NULL || prompt == NULL)
266	    {
267	      return;
268	    }
269	
270	  length = strlen(prompt);
271	  if (length == 0 || length >= sizeof(event.data.chat.text))
272	    {
273	      syslog(LOG_WARNING, "[HCI] Companion prompt length invalid: %lu\n",
274	             (unsigned long)length);
275	      return;
276	    }
277	
278	  memset(&event, 0, sizeof(event));
279	  event.type = VELAWEAR_EVENT_CHAT_INPUT;
280	  event.priority = VELAWEAR_PRIORITY_HIGH;
281	  event.timestamp = display_now_ms();
282	  event.data.chat.length = (int)length;
283	  memcpy(event.data.chat.text, prompt, length);
284	  event.data.chat.text[length] = '\0';
285	  ret = event_manager_push(display->events, &event);
286	  if (ret < 0)
287	    {
288	      syslog(LOG_WARNING, "[HCI] Companion prompt queue failed: %d\n", ret);
289	      return;
290	    }
291	
292	  display_manager_show_alert(display, "我正在想怎么陪你...");
293	  syslog(LOG_INFO, "[HCI] Companion quick prompt queued bytes=%lu\n",
294	         (unsigned long)length);
295	}
