374	static void display_detail_action_cb(lv_event_t *event)
375	{
376	  velawear_display_t *display =
377	    (velawear_display_t *)lv_event_get_user_data(event);
378	  lv_obj_t *target = lv_event_get_target(event);
379	  int action;
380	  int ret;
381	
382	  if (display == NULL || target == NULL)
383	    {
384	      return;
385	    }
386	
387	  action = (int)(uintptr_t)lv_obj_get_user_data(target);
388	  lv_event_stop_bubbling(event);
389	  ret = 0;
390	
391	  switch (action)
392	    {
393	      case DISPLAY_ACTION_AUDIO_SPEAKER:
394	      case DISPLAY_ACTION_MUSIC_PLAY:
395	        if (display->detail_hint != NULL)
396	          {
397	            lv_label_set_text(display->detail_hint, "正在播放测试旋律...");
398	          }
399	        ret = display_audio_start(display, DISPLAY_AUDIO_JOB_MELODY);
400	        if (ret > 0 && display->detail_hint != NULL)
401	          {
402	            lv_label_set_text(display->detail_hint, "测试进行中...");
403	          }
404	        else if (ret < 0 && display->detail_hint != NULL)
405	          {
406	            lv_label_set_text(display->detail_hint, "测试启动失败");
407	          }
408	        break;
409	
410	      case DISPLAY_ACTION_AUDIO_MIC:
411	        if (display->detail_hint != NULL)
412	          {
413	            lv_label_set_text(display->detail_hint, "正在采集麦克风...");
414	          }
415	        ret = display_audio_start(display, DISPLAY_AUDIO_JOB_MIC);
416	        if (ret > 0 && display->detail_hint != NULL)
417	          {
418	            lv_label_set_text(display->detail_hint, "测试进行中...");
419	          }
420	        else if (ret < 0 && display->detail_hint != NULL)
421	          {
422	            lv_label_set_text(display->detail_hint, "测试启动失败");
423	          }
424	        break;
425	
426	      case DISPLAY_ACTION_STOP_START:
427	        if (display->stopwatch_running)
428	          {
429	            display->stopwatch_elapsed_ms +=
430	              display_now_ms() - display->stopwatch_started_ms;
431	            display->stopwatch_running = false;
432	          }
433	        else
434	          {
435	            display->stopwatch_started_ms = display_now_ms();
436	            display->stopwatch_running = true;
437	          }
438	        display->last_update_ms = 0;
439	        break;
440	
441	      case DISPLAY_ACTION_STOP_RESET:
442	        display->stopwatch_running = false;
443	        display->stopwatch_started_ms = 0;
444	        display->stopwatch_elapsed_ms = 0;
445	        display->last_update_ms = 0;
446	        break;
447	
448	      case DISPLAY_ACTION_COMPANION_CHAT:
449	        display_queue_companion_prompt(display, "今天有点累，陪我聊两句");
450	        break;
451	
452	      case DISPLAY_ACTION_COMPANION_ENCOURAGE:
453	        display_queue_companion_prompt(display, "夸夸我，给我一点鼓励");
454	        break;
455	
456	      case DISPLAY_ACTION_COMPANION_REST:
457	        display_queue_companion_prompt(display, "提醒我休息一下");
458	        break;
459	
460	      default:
461	        break;
462	    }
463	}
