465	static int display_mvp_text_line(const velawear_display_t *display,
466	                                     int32_t line_count, int32_t y)
467	{
468	  lv_obj_t *label;
469	  lv_coord_t top;
470	  lv_coord_t height;
471	  lv_coord_t line_height;
472	  int32_t line;
473	
474	  if (display == NULL || line_count <= 0)
475	    {
476	      return -1;
477	    }
478	
479	  label = display->page_content[0];
480	  if (label == NULL)
481	    {
482	      return -1;
483	    }
484	
485	  top = lv_obj_get_y(label);
486	  height = lv_obj_get_height(label);
487	  line_height = height / (lv_coord_t)line_count;
488	  if (height <= 0 || line_height <= 0 || y < top || y >= top + height)
489	    {
490	      return -1;
491	    }
492	
493	  line = (y - top) / line_height;
494	  return line < line_count ? (int)line : -1;
495	}
