497	static void display_gesture_cb(lv_event_t *event)
498	{
499	  velawear_display_t *display;
500	  lv_indev_t *indev;
501	  lv_dir_t dir = LV_DIR_NONE;
502	  lv_point_t point = {0, 0};
503	  velawear_event_t touch_event;
504	  lv_event_code_t code;
505	  int app_index;
506	  int companion_line;
507	  int ret;
508	  int32_t dx;
509	  int32_t dy;
510	
511	  display = (velawear_display_t *)lv_event_get_user_data(event);
512	  indev = lv_indev_active();
513	  if (display == NULL || indev == NULL || display->detail_active)
514	    {
515	      return;
516	    }
517	
518	  code = lv_event_get_code(event);
519	  lv_indev_get_point(indev, &point);
520	  if (code == LV_EVENT_PRESSED)

520	  if (code == LV_EVENT_PRESSED)
521	    {
522	      display->touch_start = point;
523	      display->touch_tracking = true;
524	      display->touch_swipe_handled = false;
525	    }
526	  else if (code == LV_EVENT_GESTURE)
527	    {
528	      dir = lv_indev_get_gesture_dir(indev);
529	      display->touch_swipe_handled = true;
530	    }
531	
532	  memset(&touch_event, 0, sizeof(touch_event));
533	  touch_event.type = VELAWEAR_EVENT_TOUCH;
534	  touch_event.priority = VELAWEAR_PRIORITY_NORMAL;
535	  touch_event.timestamp = display_now_ms();
536	  touch_event.data.touch.x = point.x;
537	  touch_event.data.touch.y = point.y;
538	  touch_event.data.touch.gesture = code == LV_EVENT_GESTURE ?
539	                                    (int)dir : (int)code;
540	  if (display->events != NULL &&
541	      event_manager_push(display->events, &touch_event) < 0)
542	    {
543	      syslog(LOG_WARNING, "[Display] Failed to queue touch event\n");
544	    }
545	
546	  if (code == LV_EVENT_RELEASED)
547	    {
548	      dx = (int32_t)point.x - (int32_t)display->touch_start.x;
549	      dy = (int32_t)point.y - (int32_t)display->touch_start.y;
550	      if (display->touch_tracking && !display->touch_swipe_handled &&
551	          (dx <= -40 || dx >= 40) &&
552	          (dx < 0 ? -dx : dx) > (dy < 0 ? -dy : dy))
553	        {
554	          display->touch_swipe_handled = true;
555	          if (dx < 0)
556	            {
557	              display_manager_next_page(display);
558	            }
559	          else
560	            {
561	              display_manager_previous_page(display);
562	            }
563	        }
564	      display->touch_tracking = false;
565	    }
566	  else if (code == LV_EVENT_CLICKED)
567	    {
568	      if (display->touch_swipe_handled)
569	        {
570	          display->touch_swipe_handled = false;
571	          return;
572	        }
573	
574	      if (display->page_index == VELAWEAR_PAGE_APPS)
575	        {
576	          if (display->mvp_app_detail_active)
577	            {
578	              if (display->mvp_selected_app == VELAWEAR_APP_AUDIO)
579	                {
580	                  ret = display_audio_start(
581	                    display,
582	                    point.y < 220 ? DISPLAY_AUDIO_JOB_MELODY :
583	                                    DISPLAY_AUDIO_JOB_MIC);
584	                  syslog(LOG_INFO,
585	                         "[Display] audio app action y=%ld result=%d\n",
586	                         (long)point.y, ret);
587	                }
588	              else if (display->mvp_selected_app == VELAWEAR_APP_MUSIC)
589	                {
590	                  ret = display_audio_start(display,
591	                                             DISPLAY_AUDIO_JOB_MELODY);
592	                  syslog(LOG_INFO,
593	                         "[Display] music app action result=%d\n", ret);
594	                }
595	              else if (display->mvp_selected_app == VELAWEAR_APP_STOPWATCH)
596	                {
597	                  if (point.y < 270)
598	                    {
599	                      if (display->stopwatch_running)
600	                        {
601	                          display->stopwatch_elapsed_ms +=
602	                            display_now_ms() -
603	                            display->stopwatch_started_ms;
604	                          display->stopwatch_running = false;
605	                        }
606	                      else
607	                        {
608	                          display->stopwatch_started_ms = display_now_ms();
609	                          display->stopwatch_running = true;
610	                        }
611	                    }
612	                  else
613	                    {
614	                      display->stopwatch_running = false;
615	                      display->stopwatch_started_ms = 0;
616	                      display->stopwatch_elapsed_ms = 0;
617	                    }
618	                }
619	              else if (display->mvp_selected_app == VELAWEAR_APP_COMPANION)
620	                {
621	                  companion_line = display_mvp_text_line(
622	                    display, VELAWEAR_MVP_COMPANION_LINES, (int32_t)point.y);
623	                  if (companion_line == 4)
624	                    {
625	                      display_queue_companion_prompt(
626	                        display, "今天有点累，陪我聊两句");
627	                    }
628	                  else if (companion_line == 5)
629	                    {
630	                      display_queue_companion_prompt(
631	                        display, "夸夸我，给我一点鼓励");
632	                    }
633	                  else if (companion_line == 6)
634	                    {
635	                      display_queue_companion_prompt(
636	                        display, "提醒我休息一下");
637	                    }
638	                }
639	              else
640	                {
641	                  display->mvp_app_detail_active = false;
642	                }
643	
644	              display->last_update_ms = 0;
645	              return;
646	            }
647	
648	          app_index = display_mvp_text_line(display, VELAWEAR_APP_COUNT,
649	                                               (int32_t)point.y);
650	          if (app_index >= 0 && app_index < VELAWEAR_APP_COUNT)
651	            {
652	              display->mvp_selected_app = (uint8_t)app_index;
653	              display->mvp_app_detail_active = true;
654	              display->last_update_ms = 0;
655	            }
656	          return;
657	        }
658	
659	      display_manager_set_page(display,
660	                               display->page_index == VELAWEAR_PAGE_WATCHFACE ?
661	                               VELAWEAR_PAGE_APPS : VELAWEAR_PAGE_WATCHFACE);
662	    }
663	  else if (code == LV_EVENT_LONG_PRESSED)
664	    {
665	      display->touch_swipe_handled = true;
666	      display_manager_set_page(display, VELAWEAR_PAGE_WATCHFACE);
667	    }
668	  else if ((dir & LV_DIR_LEFT) != 0 || (dir & LV_DIR_TOP) != 0)
669	    {
670	      display_manager_next_page(display);
671	    }
672	  else if ((dir & LV_DIR_RIGHT) != 0 || (dir & LV_DIR_BOTTOM) != 0)
673	    {
674	      display_manager_previous_page(display);
675	    }
676	}
