1143	void display_manager_tick(velawear_display_t *display)
1144	{
1145	  uint32_t now;
1146	  velawear_state_t state;
1147	  lv_obj_t *alert_label;
1148	
1149	  if (display == NULL || !display->initialized)
1150	    {
1151	      return;
1152	    }
1153	
1154	  now = display_now_ms();
1155	  display_audio_poll(display);
1156	  pthread_mutex_lock(&display->lock);
1157	  if (display->alert_pending)
1158	    {
1159	      lv_obj_set_style_bg_color(lv_screen_active(), lv_color_hex(0x5b1111), 0);
1160	      lv_label_set_text(display->status_label, "主动提醒");
1161	      lv_obj_set_style_text_color(display->status_label,
1162	                                  lv_color_hex(0xfca5a5), 0);
1163	      alert_label = display->detail_active ? display->metrics_label :
1164	                    display->page_content[0];
1165	      if (alert_label != NULL)
1166	        {
1167	          lv_label_set_text(alert_label, display->pending_alert);
1168	          lv_obj_set_style_text_color(alert_label,
1169	                                      lv_color_hex(UI_TEXT_COLOR), 0);
1170	        }
1171	      if (g_alert_message != NULL && g_alert_overlay != NULL)
1172	        {
1173	          lv_label_set_text(g_alert_message, display->pending_alert);
1174	          lv_obj_clear_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
1175	          lv_obj_move_foreground(g_alert_overlay);
1176	        }
1177	      display->alert_until_ms = now + 60000;
1178	      display->alert_active = true;
1179	      syslog(LOG_INFO,
1180	             "[Display] Alert consumed page=%u detail=%d label=%p hold=60000ms text=%s\n",
1181	             (unsigned int)display->page_index, display->detail_active ? 1 : 0,
1182	             alert_label, display->pending_alert);
1183	      display->alert_pending = false;
1184	    }
1185	  pthread_mutex_unlock(&display->lock);
1186	
1187	  if (display->alert_active)
1188	    {
1189	      if (now < display->alert_until_ms)
1190	        {
1191	          lv_timer_handler();
1192	          return;
1193	        }
1194	
1195	      display->alert_active = false;
1196	      syslog(LOG_INFO, "[Display] Alert expired\n");
1197	      if (g_alert_overlay != NULL)
1198	        {
1199	          lv_obj_add_flag(g_alert_overlay, LV_OBJ_FLAG_HIDDEN);
1200	        }
1201	      display_restore_theme(display);
1202	      display->last_update_ms = 0;
1203	    }
1204	
1205	  if (display->last_update_ms == 0 || now - display->last_update_ms >=
1206	      (display->active_app == VELAWEAR_APP_STOPWATCH &&
1207	       display->stopwatch_running ? 100 : 250))
1208	    {
1209	      state = state_manager_get_state(display->state_mgr);
1210	      if (display->detail_active)
1211	        {
1212	          display_render_app(display, &state);
1213	        }
1214	      else
1215	        {
1216	          display_render_top(display, &state);
1217	        }
1218	      display->last_update_ms = now;
1219	    }
1220	
1221	  lv_timer_handler();
1222	}
