582	/**
583	 * Give the size of an UTF-8 coded character
584	 * @param str pointer to a character in a string
585	 * @return length of the UTF-8 character (1,2,3 or 4), 0 on invalid code.
586	 */
587	static uint8_t lv_text_utf8_size(const char * str)
588	{
589	    if(LV_IS_ASCII(str[0]))
590	        return 1;
591	    else if(LV_IS_2BYTES_UTF8_CODE(str[0]))
592	        return 2;
593	    else if(LV_IS_3BYTES_UTF8_CODE(str[0]))
594	        return 3;
595	    else if(LV_IS_4BYTES_UTF8_CODE(str[0]))
596	        return 4;
597	    return 0;
598	}
599	
600	/**
601	 * Convert a Unicode letter to UTF-8.
602	 * @param letter_uni a Unicode letter
603	 * @return UTF-8 coded character in Little Endian to be compatible with C chars (e.g. 'Á', 'Ű')
604	 */
605	static uint32_t lv_text_unicode_to_utf8(uint32_t letter_uni)
606	{
607	    if(letter_uni < 128) return letter_uni;
608	    uint8_t bytes[4];
609	
610	    if(letter_uni < 0x0800) {
611	        bytes[0] = ((letter_uni >> 6) & 0x1F) | 0xC0;
612	        bytes[1] = ((letter_uni >> 0) & 0x3F) | 0x80;
613	        bytes[2] = 0;
614	        bytes[3] = 0;
615	    }
616	    else if(letter_uni < 0x010000) {
617	        bytes[0] = ((letter_uni >> 12) & 0x0F) | 0xE0;
618	        bytes[1] = ((letter_uni >> 6) & 0x3F) | 0x80;
619	        bytes[2] = ((letter_uni >> 0) & 0x3F) | 0x80;
620	        bytes[3] = 0;
621	    }
622	    else if(letter_uni < 0x110000) {
623	        bytes[0] = ((letter_uni >> 18) & 0x07) | 0xF0;
624	        bytes[1] = ((letter_uni >> 12) & 0x3F) | 0x80;
625	        bytes[2] = ((letter_uni >> 6) & 0x3F) | 0x80;
626	        bytes[3] = ((letter_uni >> 0) & 0x3F) | 0x80;
627	    }
628	    else {
629	        return 0;
630	    }
631	
632	    uint32_t * res_p = (uint32_t *)bytes;
633	    return *res_p;
634	}
635	
636	/**
637	 * Convert a wide character, e.g. 'Á' little endian to be UTF-8 compatible
638	 * @param c a wide character or a  Little endian number
639	 * @return `c` in big endian
640	 */
641	static uint32_t lv_text_utf8_conv_wc(uint32_t c)
642	{
643	#if LV_BIG_ENDIAN_SYSTEM == 0
644	    /*Swap the bytes (UTF-8 is big endian, but the MCUs are little endian)*/
645	    if((c & 0x80) != 0) {
646	        uint32_t swapped;
647	        uint8_t c8[4];
648	        lv_memcpy(c8, &c, 4);
649	        swapped = (c8[0] << 24) + (c8[1] << 16) + (c8[2] << 8) + (c8[3]);
650	        uint8_t i;
651	        for(i = 0; i < 4; i++) {
652	            if((swapped & 0xFF) == 0)
653	                swapped = (swapped >> 8); /*Ignore leading zeros (they were in the end originally)*/
654	        }
655	        c = swapped;
656	    }
657	#endif
658	    return c;
659	}
