666	 *          NULL to use txt[0] as index
667	 * @return the decoded Unicode character or 0 on invalid UTF-8 code
668	 */
669	static uint32_t lv_text_utf8_next(const char * txt, uint32_t * i)
670	{
671	    /**
672	     * Unicode to UTF-8
673	     * 00000000 00000000 00000000 0xxxxxxx -> 0xxxxxxx
674	     * 00000000 00000000 00000yyy yyxxxxxx -> 110yyyyy 10xxxxxx
675	     * 00000000 00000000 zzzzyyyy yyxxxxxx -> 1110zzzz 10yyyyyy 10xxxxxx
676	     * 00000000 000wwwzz zzzzyyyy yyxxxxxx -> 11110www 10zzzzzz 10yyyyyy 10xxxxxx
677	     */
678	
679	    uint32_t result = 0;
680	
681	    /*Dummy 'i' pointer is required*/
682	    uint32_t i_tmp = 0;
683	    if(i == NULL) i = &i_tmp;
684	
685	    /*Normal ASCII*/
686	    if(LV_IS_ASCII(txt[*i])) {
687	        result = txt[*i];
688	        (*i)++;
689	    }
690	    /*Real UTF-8 decode*/
691	    else {
692	        /*2 bytes UTF-8 code*/
693	        if(LV_IS_2BYTES_UTF8_CODE(txt[*i])) {
694	            result = (uint32_t)(txt[*i] & 0x1F) << 6;
695	            (*i)++;
696	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
697	            result += (txt[*i] & 0x3F);
698	            (*i)++;
699	        }
700	        /*3 bytes UTF-8 code*/
701	        else if(LV_IS_3BYTES_UTF8_CODE(txt[*i])) {
702	            result = (uint32_t)(txt[*i] & 0x0F) << 12;
703	            (*i)++;
704	
705	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
706	            result += (uint32_t)(txt[*i] & 0x3F) << 6;
707	            (*i)++;
708	
709	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
710	            result += (txt[*i] & 0x3F);
711	            (*i)++;
712	        }
713	        /*4 bytes UTF-8 code*/
714	        else if(LV_IS_4BYTES_UTF8_CODE(txt[*i])) {
715	            result = (uint32_t)(txt[*i] & 0x07) << 18;
716	            (*i)++;
717	
718	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
719	            result += (uint32_t)(txt[*i] & 0x3F) << 12;
720	            (*i)++;
721	
722	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
723	            result += (uint32_t)(txt[*i] & 0x3F) << 6;
724	            (*i)++;
725	
726	            if(LV_IS_INVALID_UTF8_CODE(txt[*i])) return 0;
727	            result += txt[*i] & 0x3F;
728	            (*i)++;
729	        }
730	        else {
731	            (*i)++; /*Not UTF-8 char. Go the next.*/
732	        }
733	    }
734	    return result;
735	}
736	
737	/**
738	 * Get previous UTF-8 character form a string.
739	 * @param txt pointer to '\0' terminated string
740	 * @param i start byte index in 'txt' where to start. After the call it will point to the previous
741	 * UTF-8 char in 'txt'.
