751	    do {
752	        if(cnt >= 4) return 0; /*No UTF-8 char found before the initial*/
753	
754	        c_size = lv_text_encoded_size(&txt[*i]);
755	        if(c_size == 0) {
756	            if(*i != 0)
757	                (*i)--;
758	            else
759	                return 0;
760	        }

760	        }
761	        cnt++;
762	    } while(c_size == 0);
763	
764	    uint32_t i_tmp  = *i;
765	    uint32_t letter = lv_text_encoded_next(txt, &i_tmp); /*Character found, get it*/
766	
767	    return letter;
768	}
