771	 * Convert a character index (in an UTF-8 text) to byte index.
772	 * E.g. in "AÁRT" index of 'R' is 2th char but start at byte 3 because 'Á' is 2 bytes long
773	 * @param txt a '\0' terminated UTF-8 string
774	 * @param utf8_id character index
775	 * @return byte index of the 'utf8_id'th letter
776	 */
777	static uint32_t lv_text_utf8_get_byte_id(const char * txt, uint32_t utf8_id)
778	{
779	    uint32_t i;
780	    uint32_t byte_cnt = 0;
781	    for(i = 0; i < utf8_id && txt[byte_cnt] != '\0'; i++) {
782	        uint8_t c_size = lv_text_encoded_size(&txt[byte_cnt]);
783	        /* If the char was invalid tell it's 1 byte long*/
784	        byte_cnt += c_size ? c_size : 1;
