    95	int main(int argc, char *argv[])
    96	{
    97	  int ret;
    98	  bool falltest = argc > 1 && strcmp(argv[1], "falltest") == 0;
    99	
   100	  if (argc > 1 && strcmp(argv[1], "audio") == 0)
   101	    {
   102	      return velawear_audio_hw_test();
   103	    }
   104	
   105	  if (argc > 1 && strcmp(argv[1], "beep") == 0)
   106	    {
   107	      return velawear_speaker_alert(500, 0);
   108	    }
   109	
   110	  if (argc > 1 && strcmp(argv[1], "music") == 0)
   111	    {
   112	      return velawear_music_hw_test();
   113	    }
   114	
   115	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
   116	  if (argc > 1 && strcmp(argv[1], "mic") == 0)
   117	    {
   118	      return velawear_mic_hw_test();
   119	    }
   120	
   121	  /* Initialize agent structure */
   122	
   123	  memset(&g_agent, 0, sizeof(velawear_agent_t));
   124	  g_agent.running = false;
   125	  g_agent.watchdog_fd = -1;
   126	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
   127	  g_agent.operation_mode = VELAWEAR_MODE_ONLINE;
   128	  g_agent.imu_available = false;
   129	  g_agent.audio_available = false;
   130	  g_agent.ble_available = false;
   131	
   132	  /* Set up signal handler */
   133	
   134	  signal(SIGTERM, velawear_signal_handler);
   135	  signal(SIGINT, velawear_signal_handler);
   136	
   137	  /* Initialize subsystems */
   138	
   139	  ret = velawear_init(&g_agent);
   140	  if (ret < 0)
   141	    {
   142	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
   143	      return EXIT_FAILURE;
   144	    }
   145	
   146	  /* Start the agent */
   147	
   148	  ret = velawear_start(&g_agent);
   149	  if (ret < 0)
   150	    {
   151	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
   152	      velawear_cleanup(&g_agent);
   153	      return EXIT_FAILURE;
   154	    }
   155	
   156	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
   157	
   158	  /* Main event loop: block waiting for events.  IMU sampling runs in its
   159	   * producer thread so this task remains the single queue consumer. */
   160	  {
   161	    bool falltest_sent = false;
   162	    uint32_t last_activity_ms = velawear_now_ms();
   163	    uint32_t runtime_update_ms = 0;
   164	
   165	    while (g_agent.running)
   166	      {
   167	        velawear_event_t event;
   168	        int event_ret;
   169	        int wait_ms;
   170	        uint32_t now_ms;
   171	
   172	        now_ms = velawear_now_ms();
   173	        velawear_poll_timer(&g_agent);
   174	        if (runtime_update_ms == 0 ||
   175	            (uint32_t)(now_ms - runtime_update_ms) >= 1000)
   176	          {
   177	            state_manager_update_runtime(&g_agent.state_mgr,
   178	                                          (now_ms - g_agent.started_ms) / 1000,
   179	                                          velawear_free_memory());
   180	            runtime_update_ms = now_ms;
   181	          }
   182	
   183	        if (g_agent.power_mode == VELAWEAR_POWER_DEEP_SLEEP)
   184	          {
   185	            wait_ms = 100;
   186	          }
   187	        else if (g_agent.power_mode == VELAWEAR_POWER_LIGHT_SLEEP)
   188	          {
   189	            wait_ms = 100;
   190	          }
   191	        else if (g_agent.power_mode == VELAWEAR_POWER_IDLE)
   192	          {
   193	            wait_ms = 100;
   194	          }
   195	        else
   196	          {
   197	            wait_ms = 100;
   198	          }
   199	
   200	        if (falltest && !falltest_sent)
   201	          {
   202	            memset(&event, 0, sizeof(event));
   203	            event.type = VELAWEAR_EVENT_FALL;
   204	            event.priority = VELAWEAR_PRIORITY_CRITICAL;
   205	            if (event_manager_push(&g_agent.events, &event) < 0)
   206	              {
   207	                syslog(LOG_ERR,
   208	                       "[VelaWear] Fall self-test event enqueue failed\n");
   209	              }
   210	            else
   211	              {
   212	                syslog(LOG_INFO,
   213	                       "[VelaWear] Fall self-test event queued\n");
   214	              }
   215	            falltest_sent = true;
   216	          }
   217	
   218	        event_ret = event_manager_pop(&g_agent.events, &event, wait_ms);
   219	        if (event_ret == VELAWEAR_OK)
   220	          {
   221	            if (event.type != VELAWEAR_EVENT_MOTION)
   222	              {
   223	                last_activity_ms = velawear_now_ms();
   224	                velawear_set_power_mode(&g_agent, VELAWEAR_POWER_ACTIVE,
   225	                                        "event received");
   226	              }
   227	            event_ret = event_manager_dispatch(&g_agent.events, &event);
   228	            if (event_ret < 0)
   229	              {
   230	                syslog(LOG_WARNING,
   231	                       "[VelaWear] Event dispatch failed: %d\n", event_ret);
   232	              }
   233	            else if (falltest && event.type == VELAWEAR_EVENT_FALL)
   234	              {
   235	                /* Give action worker and main-thread display handoff time to run. */
   236	                for (int i = 0; i < 10; i++)
   237	                  {
   238	                    usleep(100000);
   239	                    display_manager_tick(&g_agent.display);
   240	                  }
   241	                g_agent.running = false;
   242	              }
   243	          }
   244	        else if (event_ret != VELAWEAR_ERR_TIMEOUT)
   245	          {
   246	          syslog(LOG_WARNING,
   247	                 "[VelaWear] Event wait failed: %d\n", event_ret);
   248	          }
   249	
   250	        velawear_buttons_poll(&g_agent.display, &last_activity_ms);
   251	
   252	        {
   253	          uint32_t idle_ms = velawear_now_ms() - last_activity_ms;
   254	
   255	          if (display_manager_is_busy(&g_agent.display))
   256	            {
   257	              /* Keep interactive apps and active tests awake. */
   258	              last_activity_ms = velawear_now_ms();
   259	            }
   260	          else if (g_agent.ble_available)
   261	            {
   262	              /* Keep the BLE MVP responsive until low-power policy is verified. */
   263	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_ACTIVE,
   264	                                      "BLE available");
   265	            }
   266	          else if (idle_ms >= 60000)
   267	            {
   268	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_DEEP_SLEEP,
   269	                                      "60 seconds without user event");
   270	            }
   271	          else if (idle_ms >= 30000)
   272	            {
   273	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_LIGHT_SLEEP,
   274	                                      "30 seconds without user event");
   275	            }
   276	          else if (idle_ms >= 10000)
   277	            {
   278	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_IDLE,
   279	                                      "10 seconds without user event");
   280	            }
   281	        }
   282	
   283	        /* Keep LVGL timers and touch input alive so sleep can be woken. */
   284	        display_manager_tick(&g_agent.display);
   285	        velawear_watchdog_ping(&g_agent);
   286	      }
   287	  }
   288	
