 53	int velawear_llm_request(velawear_llm_t *llm, const char *prompt,
 54	                         char *response, size_t response_size)
 55	{
 56	  int ret;
 57	
 58	  if (llm == NULL || !llm->initialized || prompt == NULL ||
 59	      response == NULL || response_size == 0)
 60	    {
 61	      return VELAWEAR_ERR_INVAL;
 62	    }
 63	
 64	  llm->request_count++;
 65	
 66	  ret = velawear_ble_request_llm(prompt, response, response_size, 15000);
 67	  if (ret == 0 && response[0] != '\0')
