 42	int velawear_agent_encode_event(const velawear_agent_event_t *event,
 43	                                uint8_t *frame, uint16_t frame_size)
 44	{
 45	  if (event == NULL || frame == NULL ||
 46	      frame_size < VELAWEAR_AGENT_EVENT_FRAME_SIZE)
 47	    {
 48	      return -EINVAL;
 49	    }
 50	
 51	  frame[0] = VELAWEAR_AGENT_PROTOCOL_VERSION;
 52	  frame[1] = event->event_type;
 53	  frame[2] = (uint8_t)(event->sequence & 0xff);
 54	  frame[3] = (uint8_t)(event->sequence >> 8);
 55	  frame[4] = event->priority;
 56	  frame[5] = event->intensity_percent;
 57	  frame[6] = (uint8_t)(event->value & 0xff);
 58	  frame[7] = (uint8_t)(event->value >> 8);
 59	  frame[8] = (uint8_t)(event->peak & 0xff);
 60	  frame[9] = (uint8_t)(event->peak >> 8);
 61	  frame[10] = event->flags;
 62	  return VELAWEAR_AGENT_EVENT_FRAME_SIZE;
 63	}
