 65	int velawear_agent_decode_command(const uint8_t *frame, uint16_t frame_size,
 66	                                  velawear_agent_command_t *command)
 67	{
 68	  uint8_t command_id;
 69	  uint16_t argument;
 70	
 71	  if (frame == NULL || command == NULL ||
 72	      frame_size != VELAWEAR_AGENT_COMMAND_FRAME_SIZE ||
